  render: () => {
    const root = document.createElement('div');
    root.style.cssText = ROOT_STYLE;
    const info = document.createElement('div');
    info.style.cssText = INFO_STYLE;
    info.textContent = 'Empty schedule page with no matchUps. TMX layout: matchUp catalog on the left, court grid on the right. Consumers wire date selection and issue display via their own header (see WithHeaderActions for the slot).';
    root.appendChild(info);
    const container = document.createElement('div');
    container.style.cssText = FLEX_CONTAINER;
    root.appendChild(container);
    const control = createSchedulePage(makeConfig({
      matchUpCatalog: [],
      scheduleDates: SCHEDULE_DATES,
      courtGridElement: makeMockCourtGrid(4).element
    }), container);
    addFooter(root, control);
    return root;
  }
